from typing import Dict, Optional

def char_categories(text: Optional[str]) -> Dict[str, int]:
    """Count characters by category: letters, digits, whitespace, other.

    Args:
        text: The input string.

    Returns:
        A dict with keys 'letters', 'digits', 'whitespace', 'other'.

    Examples:
        >>> char_categories("Hi 42!")
        {'letters': 2, 'digits': 2, 'whitespace': 1, 'other': 1}
        >>> char_categories("")
        {'letters': 0, 'digits': 0, 'whitespace': 0, 'other': 0}
        >>> char_categories(None)
        {'letters': 0, 'digits': 0, 'whitespace': 0, 'other': 0}
    """
    counts = {"letters": 0, "digits": 0, "whitespace": 0, "other": 0}
    if text is None:
        return counts
    for ch in text:
        if ch.isalpha():
            counts["letters"] += 1
        elif ch.isdigit():
            counts["digits"] += 1
        elif ch.isspace():
            counts["whitespace"] += 1
        else:
            counts["other"] += 1
    return counts

from typing import Dict, Optional

def char_frequency(text: Optional[str]) -> Dict[str, int]:
    """Return a dict mapping each character to its frequency in text.

    Args:
        text: The input string.

    Returns:
        A dict of counts.

    Examples:
        >>> sorted(char_frequency("hello").items())
        [('e', 1), ('h', 1), ('l', 2), ('o', 1)]
        >>> char_frequency("")
        {}
        >>> char_frequency(None)
        {}
    """
    if not text:
        return {}
    freq: Dict[str, int] = {}
    for ch in text:
        freq[ch] = freq.get(ch, 0) + 1
    return freq
